section .text._panic_index_oob progbits alloc exec nowrite align=1
; ==============================
; Runtime helper: index out of range panic
_panic_index_oob:
push rbp
mov rbp, rsp
push rbx
mov rax, 1
mov rdi, 2
lea rsi, [rel _oob_msg]
mov rdx, 21
syscall
mov rax, 60
mov rdi, 1
syscall
pop rbx
pop rbp
ret
section .text._panic_nil_deref progbits alloc exec nowrite align=1
; ==============================
; Runtime helper: nil pointer dereference panic
_panic_nil_deref:
push rbp
mov rbp, rsp
push rbx
mov rax, 1
mov rdi, 2
lea rsi, [rel _nil_msg]
mov rdx, 23
syscall
mov rax, 60
mov rdi, 1
syscall
pop rbx
pop rbp
ret
section .text._memmove progbits alloc exec nowrite align=1
; ==============================
; Runtime helper: memmove(dst, src, n)
_memmove:
push rbp
mov rbp, rsp
push rbx
mov rcx, rdx
cmp rdi, rsi
jge .memmove_rev
cld
rep movsb
jmp .memmove_done
.memmove_rev:
std
lea rsi, [rsi+rcx-1]
lea rdi, [rdi+rcx-1]
rep movsb
cld
.memmove_done:
pop rbx
pop rbp
ret

